37	export interface AxisBaseOptionCommon extends ComponentOption,
38	    AnimationOptionMixin {
39	    type?: OptionAxisType;
40	    show?: boolean;
41	    // Inverse the axis.
42	    inverse?: boolean;
43	    // Axis name displayed.
44	    name?: string;
45	    /**
46	     * - 'start': place name based on axis.extent[0].
47	     * - 'end': place name based on axis.extent[1].
48	     * - 'middle': place name based on the center of the axis.
49	     * - 'center': ='middle'.
50	     */
51	    nameLocation?: 'start' | 'middle' | 'center' | 'end';
52	    // By degree.
53	    nameRotate?: number;
54	    nameTruncate?: {
55	        maxWidth?: number;
56	        ellipsis?: string;
57	        placeholder?: string;
58	    };
59	    nameTextStyle?: AxisNameTextStyleOption;
60	    /**
61	     * This is the offset of axis name from:
62	     * - If `nameMoveOverlap: false`: offset from axisLine.
63	     * - If `nameMoveOverlap: true`: offset from axisLine+axisLabels.
64	     *
65	     * PENDING: should it named as "nameOffset" or support `[offsetX, offsetY]`?
66	     */
67	    nameGap?: number;
68	    /**
69	     * Whether to auto move axis name to avoid overlap with axis labels.
70	     * The procedure of axis name layout:
71	     * 1. Firstly apply `nameRotate`, `nameTruncate`, `nameLocation`, `nameGap`.
72	     *  Note that if `nameGap` is applied after the overlap handling, it may still
73	     *  cause overlap and confuse users.
74	     * 2. If `nameMoveOverlap: true`, move the name util it does not overlap with
75	     *  axis lables. `nameTextStyle.textMargin` can be used to adjust its gap from
76	     *  others in this case.
77	     * - If 'auto'/null/undefined, use `nameMoveOverlap`, except when `grid.containLabel` is
78	     *  true. This is for backward compat - users have tuned the position based on no name moved.
79	     */
80	    nameMoveOverlap?: boolean | 'auto' | NullUndefined;
81	
82	    silent?: boolean;
83	    triggerEvent?: boolean;
84	
85	    tooltip?: {
86	        show?: boolean;
87	    };
88	
89	    axisLabel?: AxisLabelBaseOption;
90	
91	    axisPointer?: CommonAxisPointerOption;
92	    axisLine?: AxisLineOption;
93	    axisTick?: AxisTickOption;
94	    minorTick?: MinorTickOption;
95	    splitLine?: SplitLineOption;
96	    minorSplitLine?: MinorSplitLineOption;
97	    splitArea?: SplitAreaOption;
98	
99	    /**
100	     * Min value of the axis. can be:
101	     * + ScaleDataValue
102	     * + 'dataMin': use the min value in data.
103	     * + null/undefined: auto decide min value (consider pretty look and boundaryGap).
104	     */
105	    min?: ScaleDataValue | 'dataMin' | ((extent: {min: number, max: number}) => ScaleDataValue);
106	    /**
107	     * Max value of the axis. can be:
108	     * + ScaleDataValue
109	     * + 'dataMax': use the max value in data.
110	     * + null/undefined: auto decide max value (consider pretty look and boundaryGap).
111	     */
112	    max?: ScaleDataValue | 'dataMax' | ((extent: {min: number, max: number}) => ScaleDataValue);
113	    startValue?: number;
114	
115	    jitter?: number;
116	    jitterOverlap?: boolean;
117	    jitterMargin?: number;
118	
119	    breaks?: AxisBreakOption[];
120	    breakArea?: {
121	        show?: boolean;
122	        itemStyle?: ItemStyleOption;
123	        zigzagAmplitude?: number;
124	        zigzagMinSpan?: number;
125	        zigzagMaxSpan?: number;
126	        zigzagZ: number;
127	        expandOnClick?: boolean;
128	    };
