406	function setLargeStyle(sign: number, el: LargeBoxPath, seriesModel: CandlestickSeriesModel, data: SeriesData) {
407	    // TODO put in visual?
408	    const borderColor = getBorderColor(sign, seriesModel)
409	        // Use color for border color by default.
410	        || getColor(sign, seriesModel);
411	
412	    // Color must be excluded.
413	    // Because symbol provide setColor individually to set fill and stroke
414	    const itemStyle = seriesModel.getModel('itemStyle').getItemStyle(SKIP_PROPS);
415	
416	    el.useStyle(itemStyle);
417	    el.style.fill = null;
418	    el.style.stroke = borderColor;
