20	export type JitterData = {
21	    fixedCoord: number,
22	    floatCoord: number,
23	    r: number,
24	    next: JitterData | null,
25	    prev: JitterData | null
26	};
27	
28	const inner = makeInner<{ items: JitterData }, Axis2D | SingleAxis>();
