70	function fixJitterIgnoreOverlaps(
71	    floatCoord: number,
72	    jitter: number,
73	    bandWidth: number | null,
74	    radius: number
75	): number {
76	    // Don't clamp single axis
77	    if (bandWidth === null) {
78	        return floatCoord + (Math.random() - 0.5) * jitter;
79	    }
80	    const maxJitter = bandWidth - radius * 2;
81	    const actualJitter = Math.min(Math.max(0, jitter), maxJitter);
82	    return floatCoord + (Math.random() - 0.5) * actualJitter;
83	}
84	
85	function fixJitterAvoidOverlaps(
86	    fixedAxis: Axis2D | SingleAxis,
87	    fixedCoord: number,
88	    floatCoord: number,
89	    radius: number,
90	    jitter: number,
91	    margin: number
92	): number {
93	    const store = inner(fixedAxis);
94	    if (!store.items) {
95	        store.items = {
96	            fixedCoord: -1,
97	            floatCoord: -1,
98	            r: -1,
99	            next: null,
100	            prev: null
101	        };
102	        store.items.next = store.items;
103	        store.items.prev = store.items;
104	    }
105	    const items = store.items;
106	
107	    const overlapA = placeJitterOnDirection(items, fixedCoord, floatCoord, radius, jitter, margin, 1);
108	    const overlapB = placeJitterOnDirection(items, fixedCoord, floatCoord, radius, jitter, margin, -1);
109	    const overlapResult = Math.abs(overlapA.resultCoord - floatCoord) < Math.abs(overlapB.resultCoord - floatCoord)
110	        ? overlapA : overlapB;
111	    let minFloat = overlapResult.resultCoord;
112	    // Clamp only category axis
113	    const bandWidth = fixedAxis.scale.type === 'ordinal'
114	        ? fixedAxis.getBandWidth()
115	        : null;
116	    const distance = Math.abs(minFloat - floatCoord);
117	    if (distance > jitter / 2
118	        || (bandWidth && distance > bandWidth / 2 - radius)
119	    ) {
120	        // If the new item is moved too far, then give up.
121	        // Fall back to random jitter.
122	        minFloat = fixJitterIgnoreOverlaps(floatCoord, jitter, bandWidth, radius);
123	    }
124	
125	    // Insert to store
126	    const insertBy = overlapResult.insertBy;
127	    const resultDirection = overlapResult.direction;
128	    const pointer1 = resultDirection > 0 ? 'next' : 'prev';
129	    const pointer2 = resultDirection > 0 ? 'prev' : 'next';
130	    const newItem: JitterData = {
131	        fixedCoord: fixedCoord,
132	        floatCoord: overlapResult.resultCoord,
133	        r: radius,
134	        next: null,
135	        prev: null
136	    };
137	    newItem[pointer1] = insertBy[pointer1];
138	    newItem[pointer2] = insertBy;
139	    insertBy[pointer1][pointer2] = newItem;
140	    insertBy[pointer1] = newItem;
141	
142	    return minFloat;
143	}
144	
145	function placeJitterOnDirection(
146	    items: JitterData,
147	    fixedCoord: number,
148	    floatCoord: number,
149	    radius: number,
150	    jitter: number,
151	    margin: number,
152	    direction: 1 | -1
153	): {
154	    resultCoord: number;
155	    insertBy: JitterData;
156	    direction: 1 | -1;
157	} {
158	    // Check for overlap with previous items.
159	    let y = floatCoord;
160	    const pointer1 = direction > 0 ? 'next' : 'prev';
161	    let insertBy = items;
162	    let item = items[pointer1];
163	
164	    while (item !== items) {
165	        const dx = fixedCoord - item.fixedCoord;
166	        const dy = y - item.floatCoord;
167	        const d2 = dx * dx + dy * dy;
168	        const r = radius + item.r + margin;
169	        if (d2 < r * r) {
170	            // Overlap. Try to move the new item along otherCoord direction.
171	            y = item.floatCoord + Math.sqrt(r * r - dx * dx) * direction;
172	            insertBy = item;
173	
174	            if (Math.abs(y - floatCoord) > jitter / 2) {
175	                // If the new item is moved too far, then give up.
176	                // Fall back to random jitter.
177	                return {resultCoord: Number.MAX_VALUE, insertBy, direction};
178	            }
179	        }
180	
181	        item = item[pointer1];
182	    }
183	
184	    return {resultCoord: y, insertBy, direction};
185	}

