26	
27	export default function parallelPreprocessor(option: ECUnitOption): void {
28	    createParallelIfNeeded(option);
29	    mergeAxisOptionFromParallel(option);
30	}
31	
32	/**
33	 * Create a parallel coordinate if not exists.
34	 * @inner
35	 */
36	function createParallelIfNeeded(option: ECUnitOption): void {
37	    if (option.parallel) {
38	        return;
39	    }
40	
41	    let hasParallelSeries = false;
42	
43	    zrUtil.each(option.series, function (seriesOpt: SeriesOption) {
44	        if (seriesOpt && seriesOpt.type === 'parallel') {
45	            hasParallelSeries = true;
46	        }
47	    });
48	
49	    if (hasParallelSeries) {
50	        option.parallel = [{}];
51	    }
52	}
53	
54	/**
55	 * Merge aixs definition from parallel option (if exists) to axis option.
56	 * @inner
57	 */
58	function mergeAxisOptionFromParallel(option: ECUnitOption): void {
59	    const axes = modelUtil.normalizeToArray(option.parallelAxis) as ParallelAxisOption[];
60	
61	    zrUtil.each(axes, function (axisOption) {
62	        if (!zrUtil.isObject(axisOption)) {
63	            return;
64	        }
65	
66	        const parallelIndex = axisOption.parallelIndex || 0;
67	        const parallelOption = modelUtil.normalizeToArray(option.parallel)[parallelIndex] as ParallelSeriesOption;
68	
69	        if (parallelOption && parallelOption.parallelAxisDefault) {
70	            zrUtil.merge(axisOption, parallelOption.parallelAxisDefault, false);
71	        }
72	    });
73	}

