43	export type ParallelAxisOption = AxisBaseOption & {
44	    /**
45	     * 0, 1, 2, ...
46	     */
47	    dim?: number | number[];
48	    parallelIndex?: number;
49	    areaSelectStyle?: {
50	        width?: number;
51	        borderWidth?: number;
52	        borderColor?: ZRColor;
53	        color?: ZRColor;
54	        opacity?: number;
