60	class ParallelAxisModel extends ComponentModel<ParallelAxisOption> {
61	
62	    static type: 'baseParallelAxis';
63	    readonly type = ParallelAxisModel.type;
64	
65	    axis: ParallelAxis;
66	
67	    // Inject
68	    coordinateSystem: Parallel;
69	
70	    /**
71	     * @readOnly
72	     */
73	    activeIntervals: ParallelAxisInterval[] = [];
74	
75	    getAreaSelectStyle(): ParallelAreaSelectStyleProps {
76	        return makeStyleMapper(
77	            [
78	                ['fill', 'color'],
79	                ['lineWidth', 'borderWidth'],
80	                ['stroke', 'borderColor'],
81	                ['width', 'width'],
82	                ['opacity', 'opacity']
83	                // Option decal is in `DecalObject` but style.decal is in `PatternObject`.
84	                // So do not transfer decal directly.
85	            ]
86	        )(this.getModel('areaSelectStyle')) as ParallelAreaSelectStyleProps;
87	    }
88	
89	    /**
90	     * The code of this feature is put on AxisModel but not ParallelAxis,
91	     * because axisModel can be alive after echarts updating but instance of
92	     * ParallelAxis having been disposed. this._activeInterval should be kept
93	     * when action dispatched (i.e. legend click).
94	     *
95	     * @param intervals `interval.length === 0` means set all active.
96	     */
97	    setActiveIntervals(intervals: ParallelAxisInterval[]): void {
98	        const activeIntervals = this.activeIntervals = zrUtil.clone(intervals);
99	
100	        // Normalize
101	        if (activeIntervals) {
102	            for (let i = activeIntervals.length - 1; i >= 0; i--) {
103	                numberUtil.asc(activeIntervals[i]);
104	            }
105	        }
106	    }
107	
108	    /**
109	     * @param value When only attempting detect whether 'no activeIntervals set',
110	     *        `value` is not needed to be input.
111	     */
112	    getActiveState(value?: ParsedValue): ParallelActiveState {
113	        const activeIntervals = this.activeIntervals;
114	
115	        if (!activeIntervals.length) {
116	            return 'normal';
117	        }
118	
119	        if (value == null || isNaN(+value)) {
120	            return 'inactive';
121	        }
122	
123	        // Simple optimization
124	        if (activeIntervals.length === 1) {
125	            const interval = activeIntervals[0];
126	            if (interval[0] <= value && value <= interval[1]) {
127	                return 'active';
128	            }
129	        }
130	        else {
131	            for (let i = 0, len = activeIntervals.length; i < len; i++) {
132	                if (activeIntervals[i][0] <= value && value <= activeIntervals[i][1]) {
133	                    return 'active';
134	                }
135	            }
136	        }
137	
138	        return 'inactive';
139	    }
140	
141	}
142	interface ParallelAxisModel extends AxisModelCommonMixin<ParallelAxisOption>,
143	    AxisModelExtendedInCreator {}
