155	class Line extends graphic.Group {
156	
157	    private _fromSymbolType: string;
158	    private _toSymbolType: string;
159	
160	    constructor(lineData: SeriesData, idx: number, seriesScope?: LineDrawSeriesScope) {
161	        super();
162	        this._createLine(lineData as LineList, idx, seriesScope);
163	    }
164	
165	    _createLine(lineData: LineList, idx: number, seriesScope?: LineDrawSeriesScope) {
166	        const seriesModel = lineData.hostModel;
167	        const linePoints = lineData.getItemLayout(idx);
168	        const z2 = lineData.getItemVisual(idx, 'z2');
169	        const line = createLine(linePoints);
170	        line.shape.percent = 0;
171	        graphic.initProps(line, {
172	            z2: retrieve2(z2, 0),
173	            shape: {
174	                percent: 1
175	            }
176	        }, seriesModel, idx);
177	
178	        this.add(line);
179	
180	        each(SYMBOL_CATEGORIES, function (symbolCategory) {
181	            const symbol = createSymbol(symbolCategory, lineData, idx);
182	            // symbols must added after line to make sure
183	            // it will be updated after line#update.
184	            // Or symbol position and rotation update in line#beforeUpdate will be one frame slow
185	            this.add(symbol);
186	            this[makeSymbolTypeKey(symbolCategory)] = makeSymbolTypeValue(symbolCategory, lineData, idx);
187	        }, this);
188	
189	        this._updateCommonStl(lineData, idx, seriesScope);
190	    }
191	
192	    // TODO More strict on the List type in parameters?
193	    updateData(lineData: SeriesData, idx: number, seriesScope: LineDrawSeriesScope) {
194	        const seriesModel = lineData.hostModel;
195	
196	        const line = this.childOfName('line') as ECLinePath;
197	        const linePoints = lineData.getItemLayout(idx);
198	        const target = {
199	            shape: {} as ECLinePath['shape']
200	        };
201	
202	        setLinePoints(target.shape, linePoints);
203	        graphic.updateProps(line, target, seriesModel, idx);
204	
205	        each(SYMBOL_CATEGORIES, function (symbolCategory) {
206	            const symbolType = makeSymbolTypeValue(symbolCategory, lineData as LineList, idx);
207	            const key = makeSymbolTypeKey(symbolCategory);
208	            // Symbol changed
209	            if (this[key] !== symbolType) {
210	                this.remove(this.childOfName(symbolCategory));
211	                const symbol = createSymbol(symbolCategory, lineData as LineList, idx);
212	                this.add(symbol);
213	            }
214	            this[key] = symbolType;
215	        }, this);
216	
217	        this._updateCommonStl(lineData, idx, seriesScope);
218	    };
219	
220	    getLinePath() {
221	        return this.childAt(0) as graphic.Line;
222	    }
223	
224	    _updateCommonStl(lineData: SeriesData, idx: number, seriesScope?: LineDrawSeriesScope) {
225	        const seriesModel = lineData.hostModel as SeriesModel;
226	
227	        const line = this.childOfName('line') as ECLinePath;
228	
229	        let emphasisLineStyle = seriesScope && seriesScope.emphasisLineStyle;
230	        let blurLineStyle = seriesScope && seriesScope.blurLineStyle;
231	        let selectLineStyle = seriesScope && seriesScope.selectLineStyle;
232	
233	        let labelStatesModels = seriesScope && seriesScope.labelStatesModels;
234	
235	        let emphasisDisabled = seriesScope && seriesScope.emphasisDisabled;
236	        let focus = (seriesScope && seriesScope.focus) as DefaultEmphasisFocus;
237	        let blurScope = (seriesScope && seriesScope.blurScope) as BlurScope;
238	
239	        // Optimization for large dataset
240	        if (!seriesScope || lineData.hasItemOption) {
241	            const itemModel = lineData.getItemModel<LineDrawModelOption>(idx);
242	            const emphasisModel = itemModel.getModel('emphasis');
243	
244	            emphasisLineStyle = emphasisModel.getModel('lineStyle').getLineStyle();
245	            blurLineStyle = itemModel.getModel(['blur', 'lineStyle']).getLineStyle();
246	            selectLineStyle = itemModel.getModel(['select', 'lineStyle']).getLineStyle();
247	            emphasisDisabled = emphasisModel.get('disabled');
248	            focus = emphasisModel.get('focus');
249	            blurScope = emphasisModel.get('blurScope');
250	
251	            labelStatesModels = getLabelStatesModels(itemModel);
252	        }
253	
254	        const lineStyle = lineData.getItemVisual(idx, 'style');
255	        const visualColor = lineStyle.stroke;
256	
257	        line.useStyle(lineStyle);
258	        line.style.fill = null;
259	        line.style.strokeNoScale = true;
260	
261	        line.ensureState('emphasis').style = emphasisLineStyle;
262	        line.ensureState('blur').style = blurLineStyle;
263	        line.ensureState('select').style = selectLineStyle;
264	
265	        // Update symbol
266	        each(SYMBOL_CATEGORIES, function (symbolCategory) {
267	            const symbol = this.childOfName(symbolCategory) as ECSymbol;
268	            if (symbol) {
269	                // Share opacity and color with line.
270	                symbol.setColor(visualColor);
271	                symbol.style.opacity = lineStyle.opacity;
272	
273	                for (let i = 0; i < SPECIAL_STATES.length; i++) {
274	                    const stateName = SPECIAL_STATES[i];
275	                    const lineState = line.getState(stateName);
276	                    if (lineState) {
277	                        const lineStateStyle = lineState.style || {};
278	                        const state = symbol.ensureState(stateName);
279	                        const stateStyle = state.style || (state.style = {});
280	                        if (lineStateStyle.stroke != null) {
281	                            stateStyle[symbol.__isEmptyBrush ? 'stroke' : 'fill'] = lineStateStyle.stroke;
282	                        }
283	                        if (lineStateStyle.opacity != null) {
284	                            stateStyle.opacity = lineStateStyle.opacity;
285	                        }
286	                    }
287	                }
288	
289	                symbol.markRedraw();
290	            }
291	        }, this);
292	
293	        const rawVal = seriesModel.getRawValue(idx) as number;
294	        setLabelStyle(this, labelStatesModels, {
295	            labelDataIndex: idx,
296	            labelFetcher: {
297	                getFormattedLabel(dataIndex, stateName) {
298	                    return seriesModel.getFormattedLabel(dataIndex, stateName, lineData.dataType);
299	                }
300	            },
301	            inheritColor: visualColor as ColorString || tokens.color.neutral99,
302	            defaultOpacity: lineStyle.opacity,
303	            defaultText: (rawVal == null
304	                ? lineData.getName(idx)
305	                : isFinite(rawVal)
306	                ? round(rawVal)
307	                : rawVal) + ''
308	        });
309	        const label = this.getTextContent() as InnerLineLabel;
310	
311	        // Always set `textStyle` even if `normalStyle.text` is null, because default
312	        // values have to be set on `normalStyle`.
313	        if (label) {
314	            const labelNormalModel = labelStatesModels.normal as unknown as Model<LineLabelOption>;
315	            label.__align = label.style.align;
316	            label.__verticalAlign = label.style.verticalAlign;
317	            // 'start', 'middle', 'end'
318	            label.__position = labelNormalModel.get('position') || 'middle';
319	
320	            let distance = labelNormalModel.get('distance');
321	            if (!isArray(distance)) {
322	                distance = [distance, distance];
323	            }
324	            label.__labelDistance = distance;
325	        }
326	
327	        this.setTextConfig({
328	            position: null,
329	            local: true,
330	            inside: false   // Can't be inside for stroke element.
331	        });
332	
333	        toggleHoverEmphasis(this, focus, blurScope, emphasisDisabled);
334	    }
335	
336	    highlight() {
337	        enterEmphasis(this);
338	    }
339	
340	    downplay() {
341	        leaveEmphasis(this);
342	    }
343	
344	    updateLayout(lineData: SeriesData, idx: number) {
345	        this.setLinePoints(lineData.getItemLayout(idx));
346	    }
347	
348	    setLinePoints(points: number[][]) {
349	        const linePath = this.childOfName('line') as ECLinePath;
350	        setLinePoints(linePath.shape, points);
351	        linePath.dirty();
352	    }
353	
354	    beforeUpdate() {
355	        const lineGroup = this;
356	        const symbolFrom = lineGroup.childOfName('fromSymbol') as ECSymbol;
357	        const symbolTo = lineGroup.childOfName('toSymbol') as ECSymbol;
358	        const label = lineGroup.getTextContent() as InnerLineLabel;
359	        // Quick reject
360	        if (!symbolFrom && !symbolTo && (!label || label.ignore)) {
361	            return;
362	        }
363	
364	        let invScale = 1;
365	        let parentNode = this.parent;
366	        while (parentNode) {
367	            if (parentNode.scaleX) {
368	                invScale /= parentNode.scaleX;
369	            }
370	            parentNode = parentNode.parent;
371	        }
372	
373	        const line = lineGroup.childOfName('line') as ECLinePath;
374	        // If line not changed
375	        // FIXME Parent scale changed
376	        if (!this.__dirty && !line.__dirty) {
377	            return;
378	        }
379	
380	        const percent = line.shape.percent;
381	        const fromPos = line.pointAt(0);
382	        const toPos = line.pointAt(percent);
383	
384	        const d = vector.sub([], toPos, fromPos);
385	        vector.normalize(d, d);
386	
387	        function setSymbolRotation(symbol: ECSymbol, percent: 0 | 1) {
388	            // Fix #12388
389	            // when symbol is set to be 'arrow' in markLine,
390	            // symbolRotate value will be ignored, and compulsively use tangent angle.
391	            // rotate by default if symbol rotation is not specified
392	            const specifiedRotation = (symbol as LineECSymbol).__specifiedRotation;
393	            if (specifiedRotation == null) {
394	                const tangent = line.tangentAt(percent);
395	                symbol.attr('rotation', (percent === 1 ? -1 : 1) * Math.PI / 2 - Math.atan2(
396	                    tangent[1], tangent[0]
397	                ));
398	            }
399	            else {
400	                symbol.attr('rotation', specifiedRotation);
401	            }
402	        }
403	
404	        if (symbolFrom) {
405	            symbolFrom.setPosition(fromPos);
406	            setSymbolRotation(symbolFrom, 0);
407	            symbolFrom.scaleX = symbolFrom.scaleY = invScale * percent;
408	            symbolFrom.markRedraw();
409	        }
410	        if (symbolTo) {
411	            symbolTo.setPosition(toPos);
412	            setSymbolRotation(symbolTo, 1);
413	            symbolTo.scaleX = symbolTo.scaleY = invScale * percent;
414	            symbolTo.markRedraw();
415	        }
416	
417	        if (label && !label.ignore) {
418	            label.x = label.y = 0;
419	            label.originX = label.originY = 0;
420	
421	            let textAlign: ZRTextAlign;
422	            let textVerticalAlign: ZRTextVerticalAlign;
423	
424	            const distance = label.__labelDistance;
425	            const distanceX = distance[0] * invScale;
426	            const distanceY = distance[1] * invScale;
427	            const halfPercent = percent / 2;
428	            const tangent = line.tangentAt(halfPercent);
429	            const n = [tangent[1], -tangent[0]];
430	            const cp = line.pointAt(halfPercent);
431	            if (n[1] > 0) {
432	                n[0] = -n[0];
433	                n[1] = -n[1];
434	            }
435	            const dir = tangent[0] < 0 ? -1 : 1;
436	
437	            if (label.__position !== 'start' && label.__position !== 'end') {
438	                let rotation = -Math.atan2(tangent[1], tangent[0]);
439	                if (toPos[0] < fromPos[0]) {
440	                    rotation = Math.PI + rotation;
441	                }
442	                label.rotation = rotation;
443	            }
444	
445	            let dy;
446	            switch (label.__position) {
447	                case 'insideStartTop':
448	                case 'insideMiddleTop':
449	                case 'insideEndTop':
450	                case 'middle':
451	                    dy = -distanceY;
452	                    textVerticalAlign = 'bottom';
453	                    break;
454	
455	                case 'insideStartBottom':
456	                case 'insideMiddleBottom':
457	                case 'insideEndBottom':
458	                    dy = distanceY;
459	                    textVerticalAlign = 'top';
460	                    break;
461	
462	                default:
463	                    dy = 0;
464	                    textVerticalAlign = 'middle';
465	            }
466	
467	            switch (label.__position) {
468	                case 'end':
469	                    label.x = d[0] * distanceX + toPos[0];
