310	    private _setCellId(cell: MatrixDimensionCell) {
311	        const levelsLen = this._levels.length;
312	        const dimIdx = this.dimIdx;
313	        setDimXYValue(cell.id, dimIdx, cell.firstLeafLocator, cell.level - levelsLen);
314	    }
315	
316	    private _initCellsId() {
317	        const levelsLen = this._levels.length;
318	        const dimIdx = this.dimIdx;
319	        each(this._cells, cell => {
320	            setDimXYValue(cell.id, dimIdx, cell.firstLeafLocator, cell.level - levelsLen);
321	        });
322	    }
323	
324	    private _initLevelIdOptions() {
325	        const levelsLen = this._levels.length;
326	        const dimIdx = this.dimIdx;
327	        let levelOptionList = this._model.get('levels', true);
328	        levelOptionList = isArray(levelOptionList) ? levelOptionList : [];
329	
330	        each(this._levels, (levelCfg, level) => {
331	            setDimXYValue(levelCfg.id, dimIdx, 0, level - levelsLen);
332	            levelCfg.option = levelOptionList[level];
333	        });
334	    }
