39	/**
40	 * Piece of pie including Sector, Label, LabelLine
41	 */
42	class PiePiece extends graphic.Sector {
43	
44	    constructor(data: SeriesData, idx: number, startAngle: number) {
45	        super();
46	
47	        this.z2 = 2;
48	
49	        const text = new graphic.Text();
50	
51	        this.setTextContent(text);
52	
53	        this.updateData(data, idx, startAngle, true);
54	    }
55	
56	    updateData(data: SeriesData, idx: number, startAngle?: number, firstCreate?: boolean): void {
57	        const sector = this;
58	
59	        const seriesModel = data.hostModel as PieSeriesModel;
60	        const itemModel = data.getItemModel<PieDataItemOption>(idx);
61	        const emphasisModel = itemModel.getModel('emphasis');
62	        const layout = data.getItemLayout(idx) as graphic.Sector['shape'];
63	        // cornerRadius & innerCornerRadius doesn't exist in the item layout. Use `0` if null value is specified.
64	        // see `setItemLayout` in `pieLayout.ts`.
65	        const sectorShape = extend(
66	            getSectorCornerRadius(itemModel.getModel('itemStyle'), layout, true),
67	            layout
68	        );
69	
70	        // Ignore NaN data.
71	        if (isNaN(sectorShape.startAngle)) {
72	            // Use NaN shape to avoid drawing shape.
73	            sector.setShape(sectorShape);
74	            return;
75	        }
76	
77	        if (firstCreate) {
78	            sector.setShape(sectorShape);
79	
80	            const animationType = seriesModel.getShallow('animationType');
81	            if (seriesModel.ecModel.ssr) {
82	                // Use scale animation in SSR mode(opacity?)
83	                // Because CSS SVG animation doesn't support very customized shape animation.
84	                graphic.initProps(sector, {
85	                    scaleX: 0,
86	                    scaleY: 0
87	                }, seriesModel, { dataIndex: idx, isFrom: true});
88	                sector.originX = sectorShape.cx;
89	                sector.originY = sectorShape.cy;
90	            }
91	            else if (animationType === 'scale') {
92	                sector.shape.r = layout.r0;
93	                graphic.initProps(sector, {
94	                    shape: {
95	                        r: layout.r
96	                    }
97	                }, seriesModel, idx);
98	            }
99	            // Expansion
100	            else {
101	                if (startAngle != null) {
102	                    sector.setShape({ startAngle, endAngle: startAngle });
103	                    graphic.initProps(sector, {
104	                        shape: {
105	                            startAngle: layout.startAngle,
106	                            endAngle: layout.endAngle
107	                        }
108	                    }, seriesModel, idx);
109	                }
110	                else {
111	                    sector.shape.endAngle = layout.startAngle;
112	                    graphic.updateProps(sector, {
113	                        shape: {
114	                            endAngle: layout.endAngle
115	                        }
116	                    }, seriesModel, idx);
117	                }
118	            }
119	        }
120	        else {
121	            saveOldStyle(sector);
122	            // Transition animation from the old shape
123	            graphic.updateProps(sector, {
124	                shape: sectorShape
125	            }, seriesModel, idx);
126	        }
127	
128	        sector.useStyle(data.getItemVisual(idx, 'style'));
129	
130	        setStatesStylesFromModel(sector, itemModel);
131	
132	        const midAngle = (layout.startAngle + layout.endAngle) / 2;
133	        const offset = seriesModel.get('selectedOffset');
134	        const dx = Math.cos(midAngle) * offset;
135	        const dy = Math.sin(midAngle) * offset;
136	
137	        const cursorStyle = itemModel.getShallow('cursor');
138	        cursorStyle && sector.attr('cursor', cursorStyle);
139	
140	        this._updateLabel(seriesModel, data, idx);
141	
142	        sector.ensureState('emphasis').shape = extend({
143	            r: layout.r + (emphasisModel.get('scale')
144	                ? (emphasisModel.get('scaleSize') || 0) : 0)
145	        }, getSectorCornerRadius(emphasisModel.getModel('itemStyle'), layout));
146	        extend(sector.ensureState('select'), {
147	            x: dx,
148	            y: dy,
149	            shape: getSectorCornerRadius(itemModel.getModel(['select', 'itemStyle']), layout)
150	        });
151	        extend(sector.ensureState('blur'), {
152	            shape: getSectorCornerRadius(itemModel.getModel(['blur', 'itemStyle']), layout)
153	        });
154	
155	        const labelLine = sector.getTextGuideLine();
156	        const labelText = sector.getTextContent();
157	
158	        labelLine && extend(labelLine.ensureState('select'), {
159	            x: dx,
160	            y: dy
161	        });
162	        // TODO: needs dx, dy in zrender?
163	        extend(labelText.ensureState('select'), {
164	            x: dx,
165	            y: dy
166	        });
167	
168	        toggleHoverEmphasis(
169	            this, emphasisModel.get('focus'), emphasisModel.get('blurScope'), emphasisModel.get('disabled')
170	        );
171	    }
172	
173	    private _updateLabel(seriesModel: PieSeriesModel, data: SeriesData, idx: number): void {
174	        const sector = this;
175	        const itemModel = data.getItemModel<PieDataItemOption>(idx);
176	        const labelLineModel = itemModel.getModel('labelLine');
177	
178	        const style = data.getItemVisual(idx, 'style');
179	        const visualColor = style && style.fill as ColorString;
180	        const visualOpacity = style && style.opacity;
181	
182	        setLabelStyle(
183	            sector,
184	            getLabelStatesModels(itemModel),
185	            {
186	                labelFetcher: data.hostModel as PieSeriesModel,
187	                labelDataIndex: idx,
188	                inheritColor: visualColor,
189	                defaultOpacity: visualOpacity,
190	                defaultText: seriesModel.getFormattedLabel(idx, 'normal')
191	                    || data.getName(idx)
192	            }
193	        );
194	        const labelText = sector.getTextContent();
195	
196	        // Set textConfig on sector.
197	        sector.setTextConfig({
198	            // reset position, rotation
199	            position: null,
200	            rotation: null
201	        });
202	
203	        // Make sure update style on labelText after setLabelStyle.
204	        // Because setLabelStyle will replace a new style on it.
205	        labelText.attr({
206	            z2: 10
207	        });
208	
209	        const labelPosition = itemModel.get(['label', 'position']);
210	        if (labelPosition !== 'outside' && labelPosition !== 'outer') {
211	            sector.removeTextGuideLine();
212	        }
213	        else {
214	            let polyline = this.getTextGuideLine();
215	            if (!polyline) {
216	                polyline = new graphic.Polyline();
217	                this.setTextGuideLine(polyline);
218	            }
219	
220	            // Default use item visual color
221	            setLabelLineStyle(this, getLabelLineStatesModels(itemModel), {
222	                stroke: visualColor,
223	                opacity: retrieve3(labelLineModel.get(['lineStyle', 'opacity']), visualOpacity, 1)
224	            });
225	        }
226	    }
227	}
