180	                // Calculating `percent` from `value` may be not accurate, because
181	                // This calculation can not be inversed, because all of values that
182	                // are overflow the `dataExtent` will be calculated to percent '100%'
183	                boundPercent = numberUtil.linearMap(
184	                    boundValue, dataExtent, percentExtent
185	                );
186	            }
187	
188	            // valueWindow[idx] = round(boundValue);
189	            // percentWindow[idx] = round(boundPercent);
190	            // fallback to extent start/end when parsed value or percent is invalid
191	            valueWindow[idx] = boundValue == null || isNaN(boundValue)
192	                ? dataExtent[idx]
193	                : boundValue;
194	            percentWindow[idx] = boundPercent == null || isNaN(boundPercent)
195	                ? percentExtent[idx]
196	                : boundPercent;
197	        });
198	
199	        asc(valueWindow);
200	        asc(percentWindow);
201	
202	        // The windows from user calling of `dispatchAction` might be out of the extent,
203	        // or do not obey the `min/maxSpan`, `min/maxValueSpan`. But we don't restrict window
204	        // by `zoomLock` here, because we see `zoomLock` just as a interaction constraint,
205	        // where API is able to initialize/modify the window size even though `zoomLock`
206	        // specified.
207	        const spans = this._minMaxSpan;
208	        hasPropModeValue
209	            ? restrictSet(valueWindow, percentWindow, dataExtent, percentExtent, false)
210	            : restrictSet(percentWindow, valueWindow, percentExtent, dataExtent, true);
211	
212	        function restrictSet(
213	            fromWindow: number[],
214	            toWindow: number[],
215	            fromExtent: number[],
216	            toExtent: number[],
217	            toValue: boolean
218	        ) {
219	            const suffix = toValue ? 'Span' : 'ValueSpan';
220	            sliderMove(
221	                0, fromWindow, fromExtent, 'all',
222	                spans['min' + suffix as 'minSpan' | 'minValueSpan'],
223	                spans['max' + suffix as 'maxSpan' | 'maxValueSpan']
224	            );
225	            for (let i = 0; i < 2; i++) {
226	                toWindow[i] = numberUtil.linearMap(fromWindow[i], fromExtent, toExtent, true);
227	                toValue && (toWindow[i] = scale.parse(toWindow[i]));
228	            }
229	        }
230	
231	        return {
232	            valueWindow: valueWindow,
233	            percentWindow: percentWindow
234	        };
235	    }
236	
237	    /**
238	     * Notice: reset should not be called before series.restoreData() is called,
239	     * so it is recommended to be called in "process stage" but not "model init
240	     * stage".
241	     */
242	    reset(dataZoomModel: DataZoomModel) {
243	        if (dataZoomModel !== this._dataZoomModel) {
244	            return;
245	        }
246	
247	        const targetSeries = this.getTargetSeriesModels();
248	        // Culculate data window and data extent, and record them.
249	        this._dataExtent = calculateDataExtent(this, this._dimName, targetSeries);
250	
251	        // `calculateDataWindow` uses min/maxSpan.
252	        this._updateMinMaxSpan();
253	
254	        const dataWindow = this.calculateDataWindow(dataZoomModel.settledOption);
255	
256	        this._valueWindow = dataWindow.valueWindow;
257	        this._percentWindow = dataWindow.percentWindow;
258	
259	        // Update axis setting then.
260	        this._setAxisModel();
261	    }
262	
263	    filterData(dataZoomModel: DataZoomModel, api: ExtensionAPI) {
264	        if (dataZoomModel !== this._dataZoomModel) {
265	            return;
266	        }
267	
268	        const axisDim = this._dimName;
269	        const seriesModels = this.getTargetSeriesModels();
270	        const filterMode = dataZoomModel.get('filterMode');
271	        const valueWindow = this._valueWindow;
272	
273	        if (filterMode === 'none') {
274	            return;
275	        }
276	
277	        // FIXME
278	        // Toolbox may has dataZoom injected. And if there are stacked bar chart
279	        // with NaN data, NaN will be filtered and stack will be wrong.
280	        // So we need to force the mode to be set empty.
281	        // In fect, it is not a big deal that do not support filterMode-'filter'
282	        // when using toolbox#dataZoom, utill tooltip#dataZoom support "single axis
283	        // selection" some day, which might need "adapt to data extent on the
284	        // otherAxis", which is disabled by filterMode-'empty'.
285	        // But currently, stack has been fixed to based on value but not index,
286	        // so this is not an issue any more.
287	        // let otherAxisModel = this.getOtherAxisModel();
288	        // if (dataZoomModel.get('$fromToolbox')
289	        //     && otherAxisModel
290	        //     && otherAxisModel.hasSeriesStacked
291	        // ) {
292	        //     filterMode = 'empty';
293	        // }
294	
295	        // TODO
296	        // filterMode 'weakFilter' and 'empty' is not optimized for huge data yet.
297	
298	        each(seriesModels, function (seriesModel) {
299	            let seriesData = seriesModel.getData();
300	            const dataDims = seriesData.mapDimensionsAll(axisDim);
301	
302	            if (!dataDims.length) {
303	                return;
304	            }
305	
306	            if (filterMode === 'weakFilter') {
307	                const store = seriesData.getStore();
308	                const dataDimIndices = zrUtil.map(dataDims, dim => seriesData.getDimensionIndex(dim), seriesData);
309	                seriesData.filterSelf(function (dataIndex) {
310	                    let leftOut;
311	                    let rightOut;
312	                    let hasValue;
313	                    for (let i = 0; i < dataDims.length; i++) {
314	                        const value = store.get(dataDimIndices[i], dataIndex) as number;
315	                        const thisHasValue = !isNaN(value);
316	                        const thisLeftOut = value < valueWindow[0];
317	                        const thisRightOut = value > valueWindow[1];
318	                        if (thisHasValue && !thisLeftOut && !thisRightOut) {
319	                            return true;
320	                        }
321	                        thisHasValue && (hasValue = true);
322	                        thisLeftOut && (leftOut = true);
323	                        thisRightOut && (rightOut = true);
324	                    }
325	                    // If both left out and right out, do not filter.
326	                    return hasValue && leftOut && rightOut;
327	                });
328	            }
329	            else {
330	                each(dataDims, function (dim) {
331	                    if (filterMode === 'empty') {
332	                        seriesModel.setData(
333	                            seriesData = seriesData.map(dim, function (value: number) {
334	                                return !isInWindow(value) ? NaN : value;
335	                            })
336	                        );
337	                    }
338	                    else {
339	                        const range: Dictionary<[number, number]> = {};
340	                        range[dim] = valueWindow;
341	
342	                        // console.time('select');
343	                        seriesData.selectRange(range);
344	                        // console.timeEnd('select');
345	                    }
346	                });
347	            }
348	
349	            each(dataDims, function (dim) {
350	                seriesData.setApproximateExtent(valueWindow, dim);
351	            });
352	        });
353	
354	        function isInWindow(value: number) {
355	            return value >= valueWindow[0] && value <= valueWindow[1];
356	        }
357	    }
358	
359	    private _updateMinMaxSpan() {
360	        const minMaxSpan = this._minMaxSpan = {} as MinMaxSpan;
361	        const dataZoomModel = this._dataZoomModel;
362	        const dataExtent = this._dataExtent;
363	
364	        each(['min', 'max'], function (minMax) {
365	            let percentSpan = dataZoomModel.get(minMax + 'Span' as 'minSpan' | 'maxSpan');
366	            let valueSpan = dataZoomModel.get(minMax + 'ValueSpan' as 'minValueSpan' | 'maxValueSpan');
367	            valueSpan != null && (valueSpan = this.getAxisModel().axis.scale.parse(valueSpan));
368	
369	            // minValueSpan and maxValueSpan has higher priority than minSpan and maxSpan
370	            if (valueSpan != null) {
371	                percentSpan = numberUtil.linearMap(
372	                    dataExtent[0] + valueSpan, dataExtent, [0, 100], true
373	                );
374	            }
375	            else if (percentSpan != null) {
376	                valueSpan = numberUtil.linearMap(
377	                    percentSpan, [0, 100], dataExtent, true
378	                ) - dataExtent[0];
379	            }
380	
381	            minMaxSpan[minMax + 'Span' as 'minSpan' | 'maxSpan'] = percentSpan;
382	            minMaxSpan[minMax + 'ValueSpan' as 'minValueSpan' | 'maxValueSpan'] = valueSpan;
383	        }, this);
384	    }
385	
386	    private _setAxisModel() {
387	
388	        const axisModel = this.getAxisModel();
389	
390	        const percentWindow = this._percentWindow;
391	        const valueWindow = this._valueWindow;
392	
393	        if (!percentWindow) {
394	            return;
395	        }
396	
397	        // [0, 500]: arbitrary value, guess axis extent.
398	        let precision = numberUtil.getPixelPrecision(valueWindow, [0, 500]);
399	        precision = Math.min(precision, 20);
400	
401	        // For value axis, if min/max/scale are not set, we just use the extent obtained
402	        // by series data, which may be a little different from the extent calculated by
403	        // `axisHelper.getScaleExtent`. But the different just affects the experience a
404	        // little when zooming. So it will not be fixed until some users require it strongly.
405	        const rawExtentInfo = axisModel.axis.scale.rawExtentInfo;
406	        if (percentWindow[0] !== 0) {
407	            rawExtentInfo.setDeterminedMinMax('min', +valueWindow[0].toFixed(precision));
408	        }
409	        if (percentWindow[1] !== 100) {
410	            rawExtentInfo.setDeterminedMinMax('max', +valueWindow[1].toFixed(precision));
411	        }
412	        rawExtentInfo.freeze();
413	    }
414	}
415	
416	function calculateDataExtent(axisProxy: AxisProxy, axisDim: string, seriesModels: SeriesModel[]) {
417	    const dataExtent = [Infinity, -Infinity];
418	
419	    each(seriesModels, function (seriesModel) {
420	        unionAxisExtentFromData(dataExtent, seriesModel.getData(), axisDim);
421	    });
422	
423	    // It is important to get "consistent" extent when more then one axes is
424	    // controlled by a `dataZoom`, otherwise those axes will not be synchronized
425	    // when zooming. But it is difficult to know what is "consistent", considering
426	    // axes have different type or even different meanings (For example, two
427	    // time axes are used to compare data of the same date in different years).
428	    // So basically dataZoom just obtains extent by series.data (in category axis
429	    // extent can be obtained from axis.data).
430	    // Nevertheless, user can set min/max/scale on axes to make extent of axes
431	    // consistent.
432	    const axisModel = axisProxy.getAxisModel();
433	    const rawExtentResult = ensureScaleRawExtentInfo(axisModel.axis.scale, axisModel, dataExtent).calculate();
434	
435	    return [rawExtentResult.min, rawExtentResult.max] as [number, number];
436	}
437	
438	export default AxisProxy;

