        chart = createChart();
        expect(function () {
            chart.setOption({
                dataset: {
                    source: [
                        ['', 'val'],
                        ['a', 10],
                        ['b', 20],
                        ['c', 15]
                    ]
                },
                xAxis: { type: 'category' },
                yAxis: {},
                series: [{ type: 'line', areaStyle: {} }]
            });
            chart.setOption({
                dataset: {
                    source: [
                        ['', 'val'],
                        ['a', 12],
                        ['b', 18],
                        ['c', 25]
                    ]
                }
            });
        }).not.toThrow();
    });

    it('stacked lines with empty dim name', function () {
        chart = createChart();
        expect(function () {
