describe('axisLabel formatter index with customValues', function () {

    it('formatter receives the index of each displayed custom tick', function () {
        const chart = createChart();
        const calls: [number, number][] = [];
        chart.setOption({
            xAxis: {
                type: 'value',
                min: 0,
                max: 100,
                axisLabel: {
                    // -10 and 150 are out of the axis extent and filtered out.
                    customValues: [-10, 0, 20, 50, 150],
                    formatter: function (value: number, index: number) {
                        calls.push([value, index]);
                        return String(value);
                    }
                }
            },
            series: []
        });

        expect(calls).toContainEqual([0, 0]);
        expect(calls).toContainEqual([20, 1]);
        expect(calls).toContainEqual([50, 2]);
        // Filtered out values should never be formatted.
        expect(calls.find(c => c[0] === -10)).toBeUndefined();
        expect(calls.find(c => c[0] === 150)).toBeUndefined();

        removeChart(chart);
    });

});

