import { createChart, removeChart } from '../../test/ut/core/utHelper';

describe('axisLabel formatter indexing with customValues', function () {

    it('duplicate values do not collapse onto the first matching position', function () {
        const chart = createChart();
        const calls: [number, number][] = [];
        chart.setOption({
            xAxis: {
                type: 'value',
                min: 0,
                max: 100,
                axisLabel: {
                    // 20 appears twice; -5 is filtered out by the extent.
                    customValues: [-5, 10, 20, 20, 30],
                    formatter: function (value: number, index: number) {
                        calls.push([value, index]);
                        return String(value);
                    }
                }
            },
            yAxis: {
                type: 'value'
            },
            series: [{type: 'line', data: [[10, 10], [90, 90]]}]
        });

        // The index is the position in the filtered label sequence,
        // so the duplicated 20 must be seen at both index 1 and index 2.
        expect(calls).toContainEqual([10, 0]);
        expect(calls).toContainEqual([20, 1]);
        expect(calls).toContainEqual([20, 2]);
        expect(calls).toContainEqual([30, 3]);
        expect(calls.find(c => c[0] === -5)).toBeUndefined();

        removeChart(chart);
    });

});

